import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";import"./chunks/assets.B-QExMyb.js";var i=JSON.parse(`{"title":"[Chapter 3] Remote Login","description":"","frontmatter":{},"headers":[],"relativePath":"en/document/level-0/ch03-ssh.md","filePath":"en/document/level-0/ch03-ssh.md","lastUpdated":1769207840000}`),a={name:`en/document/level-0/ch03-ssh.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="chapter-3-remote-login" tabindex="-1">[Chapter 3] Remote Login <a class="header-anchor" href="#chapter-3-remote-login" aria-label="Permalink to “[Chapter 3] Remote Login”">​</a></h1><h2 id="_3-1-remote-login-to-vps-putty" tabindex="-1">3.1 Remote Login to VPS (PuTTY) <a class="header-anchor" href="#_3-1-remote-login-to-vps-putty" aria-label="Permalink to “3.1 Remote Login to VPS (PuTTY)”">​</a></h2><p>First, given that Windows has the largest user base among beginners, this article will use Windows as an example.</p><p>Secondly, although modern Windows 10 and later versions feature PowerShell and WSL which offer a great SSH experience, not all versions of Windows have the latest components. Therefore, we will use the classic tool <strong>PuTTY</strong> for this detailed SSH tutorial. (If you use other tools, the operations after logging in are identical.)</p><p>Now, follow me step by step.</p><ol><li><p>Go to PuTTY&#39;s <a href="https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html" target="_blank" rel="noreferrer">official website</a> and download the version suitable for your operating system (this article uses the 64-bit version).</p><p><img src="/assets/ch03-img01-putty-download.Bz5MUwAJ.png" alt="Download PuTTY" width="1197" height="787"></p></li><li><p>After installation, open PuTTY. Now, take out the <a href="./ch02-preparation.html#_21-getting-a-vps">notebook</a> where you jotted things down in the previous chapter. Fill in your VPS <strong>IP Address</strong> and <strong>Port</strong> in the corresponding fields shown below. To avoid typing this every time, we can save the session. Just click <code>Save</code> under Saved Sessions, and in the future, click <code>Load</code> to restore settings instantly.</p><p><img src="/assets/ch03-img02-putty-settings.DjkSkJO_.png" alt="Configure PuTTY" width="466" height="448"></p></li><li><p>I suggest setting <code>Seconds between keepalives</code> under <code>Connection</code> to <code>60</code>. This prevents SSH from automatically disconnecting due to inactivity. <strong>Make sure to save your session settings again.</strong></p><p><img src="/assets/ch03-img03-putty-keepalive.BlaoAerP.png" alt="Prevent frequent disconnections" width="466" height="448"></p></li></ol><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Any setting updates in PuTTY must be manually saved to the Session again, otherwise, they will be lost when you close the program.</p></div><ol><li><p>Click <code>Open</code> to enter the SSH connection window. Enter your username and password as shown below to connect to your VPS. (This article assumes the default username is <code>root</code>. Also, when typing passwords in Linux, **no asterisks <code>\\*\\*\\*\\***</code> will appear**. This prevents password length leakage—your keyboard isn&#39;t broken!)</p><p><img src="/assets/ch03-img04-ssh-login.CzV3PNlG.png" alt="SSH Remote Login" width="835" height="640"></p></li></ol><h2 id="_3-2-successfully-logged-into-ssh-meet-the-command-line-interface" tabindex="-1">3.2 Successfully Logged into SSH! Meet the Command Line Interface <a class="header-anchor" href="#_3-2-successfully-logged-into-ssh-meet-the-command-line-interface" aria-label="Permalink to “3.2 Successfully Logged into SSH! Meet the Command Line Interface”">​</a></h2><ol><li><p>If you entered everything correctly, you will see a screen similar to the one below, indicating a successful login:</p><p><img src="/assets/ch03-img05-ssh-login-success.l_VdE5HU.png" alt="First Login to VPS" width="835" height="640"></p><p>This interface is the remote server&#39;s [Desktop], but without the icons, mouse, or colorful graphics you are used to. It&#39;s just simple text. This is the <strong>Command Line Interface</strong> (CLI).</p><p>All subsequent operations require you to work in this interface, just like a hacker in the movies. It might feel strange, but trust me, the command line is neither scary nor mysterious. Ultimately, it just turns your mouse clicks into text commands: <strong>You say it, it does it</strong>.</p></li><li><p>Now, look around and get familiar with the CLI environment. This interface actually tells you some useful info, like the system kernel version (e.g., <code>4.19.37-5</code> in the image), last login time, and IP. Of course, depending on your VPS, what you see might differ slightly.</p></li><li><p>Pay attention to the last line, to the left of the flashing cursor. There is a string of characters. In the image, it shows <code>root@vps-server:~#</code>. How should you understand this? Simple:</p><ul><li>The current user is <code>root</code></li><li>The server <code>root</code> is on is <code>vps-server</code></li><li>The folder <code>root</code> is currently in is <code>~</code></li><li>The <code>#</code> indicates where you can type commands</li></ul><p>The first two are intuitive. The third is about the Linux file system; for now, just know that &quot;<code>~</code>&quot; is the [Current User&#39;s Home Base]. The fourth, the prompt <code>#</code>, doesn&#39;t need much thought. Just know that in future articles, commands you need to type will start with <code>#</code> or <code>$</code>, indicating <strong>where</strong> you start typing. (So when copying commands, <strong>only copy the content after this symbol</strong>, do not copy the prompt itself.)</p></li></ol><h2 id="_3-3-updating-linux-software-for-the-first-time" tabindex="-1">3.3 Updating Linux Software for the First Time <a class="header-anchor" href="#_3-3-updating-linux-software-for-the-first-time" aria-label="Permalink to “3.3 Updating Linux Software for the First Time”">​</a></h2><ol><li><p>Just like your phone (Android or iPhone) checks the App Store for updates (security patches and new features), Linux has a very similar update logic. If you can update apps on your phone, you can update Linux software!</p></li><li><p>In Linux, every app is called a &quot;package&quot;. The program that manages apps is naturally called the &quot;Package Manager&quot;. You can install, update, and uninstall software, or even update the Linux system itself through it. The package manager is powerful, but for now, you only need to know that the Debian system&#39;s manager is called <code>apt</code>. Next, let&#39;s use <code>apt</code> to perform a full software update to get familiar with it.</p></li><li><p>Basic Linux commands for beginners:</p><table tabindex="0"><thead><tr><th style="text-align:center;">Code</th><th style="text-align:center;">Command Name</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;"><code>cmd-01</code></td><td style="text-align:center;"><code>apt update</code></td><td style="text-align:center;">Check for software updates</td></tr><tr><td style="text-align:center;"><code>cmd-02</code></td><td style="text-align:center;"><code>apt upgrade</code></td><td style="text-align:center;">Execute software updates</td></tr></tbody></table></li><li><p>Now enter the first command to fetch update information:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">apt</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> update</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>Then enter the second command. When asked whether to continue <code>(Y/n)</code>, type <code>y</code> and hit Enter to start the installation:</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes dark-plus light-plus" style="--shiki-dark:#D4D4D4;--shiki-light:#000000;--shiki-dark-bg:#1E1E1E;--shiki-light-bg:#FFFFFF;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#DCDCAA;--shiki-light:#795E26;">apt</span><span style="--shiki-dark:#CE9178;--shiki-light:#A31515;"> upgrade</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p>The complete process is demonstrated below:</p><p><img src="/assets/ch03-img06-apt-upgrade-full.-w3BBGrx.gif" alt="First Software Update Demo" width="839" height="644"></p></li></ol><h2 id="_3-4-your-progress" tabindex="-1">3.4 Your Progress <a class="header-anchor" href="#_3-4-your-progress" aria-label="Permalink to “3.4 Your Progress”">​</a></h2><p><strong>Congratulations on taking another solid step!</strong> Now, you can log in to your remote server via SSH! After logging in and updating software, what should you do next? Head to the next chapter to find out!</p><blockquote><p>⬛⬛⬛⬜⬜⬜⬜⬜ 37.5%</p></blockquote>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};